    for (;;) {
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);       /* one notification per resync */
        for (i = 0; i < s_n; i++) {
            xTimerReset(s_tmr[i], portMAX_DELAY);      /* expiry = now + period */
        }
    }
}

